"""NumPy execution backend for programs generated by Carrier.exportPython (#278).

The exporter and this carrier are trusted, outside the Lean adequacy theorem.
Install numpy and ml_dtypes for this backend. Run a generated module's run()
from Python, or use the existing little-endian VTTENSR1 files from the CLI:

  python -m scripts.interp.pyexec kernel.py --grid 4,1,1 \
      --tensor X=x.tensor --tensor O=initial.tensor --output O=result.tensor

The CLI executes the supplied Python program. Region arrays must be supplied for
both inputs and outputs. Active out-of-range and uninitialized masked loads fail.
The fused fp32 operation uses libm.fmaf lane by lane for one rounding. Reductions
and matrix products follow NumPy's order at the exported dtype.
"""
import argparse
import ctypes
import ctypes.util
from functools import lru_cache
from itertools import product
import runpy

import ml_dtypes
import numpy as np

from . import tensorfile


DTYPES = {
    'fp32': np.dtype('float32'), 'fp16': np.dtype('float16'), 'bf16': np.dtype(ml_dtypes.bfloat16),
    'fp64': np.dtype('float64'), 'f8e4': np.dtype(ml_dtypes.float8_e4m3fn),
    'f8e5': np.dtype(ml_dtypes.float8_e5m2), 'bool': np.dtype('bool'),
    'int': np.dtype(object), 'nat': np.dtype(object),
    **{name: np.dtype(name) for name in tensorfile.DTYPES if name.startswith(('int', 'uint'))},
}
FLOAT_LAYOUT = {'fp16': (5, 10), 'fp32': (8, 23), 'fp64': (11, 52),
                'bf16': (8, 7), 'f8e4': (4, 3), 'f8e5': (5, 2)}
UNARY = {'neg': np.negative, 'abs': np.absolute, 'boolNot': np.logical_not,
         'exp': np.exp, 'exp2': np.exp2, 'log': np.log, 'log2': np.log2,
         'sqrt': np.sqrt, 'tanh': np.tanh, 'sin': np.sin, 'cos': np.cos,
         'tan': np.tan, 'atan': np.arctan, 'cosh': np.cosh, 'sinh': np.sinh,
         'expm1': np.expm1, 'log1p': np.log1p, 'isFinite': np.isfinite}
BINARY = {'add': np.add, 'sub': np.subtract, 'mul': np.multiply, 'div': np.divide,
          'floorDiv': np.floor_divide, 'mod': np.mod, 'lt': np.less, 'le': np.less_equal,
          'eq': np.equal, 'gt': np.greater, 'ge': np.greater_equal, 'ne': np.not_equal,
          'boolAnd': np.logical_and, 'boolOr': np.logical_or, 'max2': np.maximum,
          'maximumFloat': np.maximum, 'minimumFloat': np.minimum, 'pow': np.power}


def _word(dtype, bits):
    if dtype in ('int', 'nat'):
        raise ValueError('raw words require a fixed-width dtype')
    itemsize = DTYPES[dtype].itemsize
    if not 0 <= bits < 1 << (8 * itemsize):
        raise ValueError(f'{dtype} payload exceeds the word width')
    return np.array(bits, dtype=f'u{itemsize}').view(DTYPES[dtype])


@lru_cache(maxsize=1024)
def _literal(dtype, n, d):
    """Round the exported rational *once* to its format, including halfway values."""
    if d <= 0:
        raise ValueError('literal denominator must be positive')
    if dtype not in FLOAT_LAYOUT:
        if d != 1 or dtype == 'nat' and n < 0 or dtype == 'bool' and n not in (0, 1):
            raise ValueError(f'invalid {dtype} literal')
        return np.array(n, dtype=DTYPES[dtype])
    ebits, fbits = FLOAT_LAYOUT[dtype]
    bias = (1 << (ebits - 1)) - 1
    sign = int(n < 0) << (ebits + fbits)
    n = abs(n)
    if not n:
        return _word(dtype, 0)
    exponent = n.bit_length() - d.bit_length()
    if (n << max(0, -exponent)) < (d << max(0, exponent)):
        exponent -= 1
    exponent = max(exponent, 1 - bias)
    shift = fbits - exponent
    divisor = d << max(-shift, 0)
    mantissa, remainder = divmod(n << max(shift, 0), divisor)
    mantissa += 2 * remainder > divisor or (2 * remainder == divisor and mantissa % 2)
    # Adding the implicit leading bit here also handles carries and subnormals.
    magnitude = ((exponent + bias - 1) << fbits) + mantissa
    upper = ((1 << ebits) - 1) << fbits
    if dtype == 'f8e4':   # finite e4m3fn reserves its highest magnitude for NaN
        upper |= (1 << fbits) - 1
    return _word(dtype, sign | min(magnitude, upper))


@lru_cache(maxsize=1)
def _fmaf():
    libm = ctypes.CDLL(ctypes.util.find_library('m'))
    f = libm.fmaf
    f.argtypes = [ctypes.c_float] * 3
    f.restype = ctypes.c_float
    return np.vectorize(f, otypes=[np.float32])


def _integers(a):
    """Keep mathematical Nat/Int indices exact beyond binary64 and int64."""
    a = np.asarray(a)
    if a.dtype.kind not in 'iuO':
        raise ValueError('expected integer coordinates')
    if a.dtype.kind == 'O' and any(not isinstance(v, (int, np.integer)) for v in a.flat):
        raise ValueError('expected integer coordinates')
    return a.astype(object)


def _euclid(a, b, mod):
    # Lean's div/mod use a nonnegative remainder even with a negative divisor.
    # At zero, a/0 = 0 and a%0 = a.
    divisor = np.where(b == 0, 1, np.abs(b))
    remainder = np.mod(a, divisor)
    if mod:
        return np.where(b == 0, a, remainder)
    return np.where(b == 0, 0, np.floor_divide(a, divisor) * np.sign(b))


def _coordinates(region, offsets, active, shape):
    offsets = np.broadcast_to(_integers(offsets), shape)
    enabled = np.broadcast_to(active, shape)
    if enabled.dtype != np.bool_:
        raise ValueError('memory mask must be Boolean')
    selected = offsets[enabled]
    if np.any(selected < 0) or np.any(selected >= region.size):
        raise IndexError('active memory address is outside the supplied region')
    return enabled, selected.astype(np.intp)


def _storage_dtype(name, array):
    if name == 'nat':
        valid = array.dtype.kind == 'u'
    elif name == 'int':
        valid = array.dtype.kind == 'i'
    else:
        valid = array.dtype == DTYPES[name]
    if not valid:
        raise ValueError(f'{name} memory access has storage dtype {array.dtype}')


class _CTA:
    def __init__(self, memory, regs, pid, grid):
        self.memory, self.regs, self.pid, self.grid = memory, dict(regs), pid, grid

    def expr(self, expression):
        tag, dtype, dims, *args = expression
        shape = tuple(dims)
        dt = DTYPES[dtype]
        if tag == 'const':
            result = _literal(dtype, *args)
        elif tag == 'bits':
            result = _word(dtype, args[0])
        elif tag in ('negInf', 'posInf'):
            result = np.full(shape, -np.inf if tag == 'negInf' else np.inf, dtype=dt)
        elif tag == 'ref':
            result = self.regs[args[0]]
        elif tag in ('programId', 'numPrograms'):
            coords = self.pid if tag == 'programId' else self.grid
            axis = args[0]
            if not 0 <= axis < 3:
                raise ValueError('program axis must be 0, 1 or 2')
            result = coords[axis]
        elif tag == 'arange':
            result = np.arange(args[0], dtype=object)
        elif tag in ('full', 'broadcast'):
            result = np.broadcast_to(self.expr(args[0]), shape)
        elif tag == 'bitcast':
            source, expr = args
            a = self.expr(expr)
            if (source in ('nat', 'int') or dtype in ('nat', 'int')
                    or a.dtype != DTYPES[source] or a.dtype.itemsize != dt.itemsize):
                raise ValueError('bitcast requires fixed formats of the same width')
            result = a.view(dt)
        elif tag == 'cast':
            result = self.expr(args[0])
            if dtype in FLOAT_LAYOUT and args[0][1] in ('int', 'nat'):
                exact = np.frompyfunc(lambda x: _literal(dtype, int(x), 1)[()], 1, 1)
                result = exact(result)
            elif dtype in ('nat', 'int'):
                result = np.frompyfunc(int, 1, 1)(result)
                if dtype == 'nat':
                    result = np.maximum(result, 0)
        elif tag == 'dot':
            x, y = (self.expr(e) for e in args)
            if dtype not in ('fp32', 'fp64') or x.dtype != dt or y.dtype != dt:
                raise ValueError('dot requires matching input and accumulation formats')
            result = np.matmul(x, y)
        elif tag == 'reshape':
            result = self.expr(args[0]).reshape(shape)
        elif tag == 'transpose':
            result = self.expr(args[0]).swapaxes(-1, -2)
        elif tag in ('reduceSum', 'reduceMin', 'reduceMax'):
            axis, keep, child = args
            x = self.expr(child)
            if not 0 <= axis < x.ndim:
                raise ValueError(f'invalid reduction axis {axis}')
            if tag == 'reduceSum':
                result = np.sum(x, axis=axis, keepdims=keep, dtype=dt)
            else:
                result = (np.min if tag == 'reduceMin' else np.max)(x, axis=axis, keepdims=keep)
        elif tag == 'ite':
            cond, yes, no = args
            result = self.expr(yes if self.expr(cond).item() else no)
        elif tag == 'where':
            result = np.where(*(self.expr(e) for e in args))
        elif tag == 'load':
            name, offset, mask, other, padding = args
            if padding != 'none':
                raise ValueError('region loads have no block-pointer padding')
            region = self.memory[name]
            _storage_dtype(dtype, region)
            active, index = _coordinates(region, self.expr(offset),
                                         np.asarray(True) if mask is None else self.expr(mask), shape)
            if other is None and not np.all(active):
                raise ValueError('masked load has unspecified inactive lanes')
            result = np.empty(shape, dtype=dt) if other is None else np.array(
                np.broadcast_to(self.expr(other), shape), dtype=dt, copy=True)
            result[active] = region.flat[index]
        elif tag in UNARY:
            result = UNARY[tag](self.expr(args[0]))
        elif tag in ('rsqrt', 'sigmoid'):
            x = self.expr(args[0])
            one = np.ones((), dtype=dt)
            result = one / (np.sqrt(x) if tag == 'rsqrt' else one + np.exp(-x))
        elif tag in BINARY:
            a, b = (self.expr(e) for e in args)
            if dtype in ('nat', 'int') and tag in ('div', 'floorDiv', 'mod'):
                result = _euclid(a, b, tag == 'mod')
            elif dtype == 'nat' and tag == 'sub':
                result = np.maximum(np.subtract(a, b), 0)
            else:
                result = BINARY[tag](a, b)
        elif tag == 'fma':
            if dtype != 'fp32':
                raise ValueError('fma is exported only for single-rounded fp32')
            result = _fmaf()(*(self.expr(e) for e in args))
        else:
            raise ValueError(f'unsupported exported expression {tag!r}')
        result = np.asarray(result, dtype=dt)
        if result.shape != shape:
            raise ValueError(f'{tag}: expected shape {shape}, produced {result.shape}')
        if dtype in ('fp32', 'bf16') and tag in ('add', 'sub', 'mul', 'div', 'fma'):
            # FPValue.ieeeValue canonicalizes arithmetic NaNs; loads and sign
            # operations retain the input bits (including a signaling NaN).
            result = np.where(np.isnan(result), np.array(np.nan, dtype=dt), result)
        return result

    def block(self, body):
        for tag, *args in body:
            if tag == 'assign':
                name, expr = args
                self.regs[name] = self.expr(expr)
            elif tag == 'if':
                cond, yes, no = args
                self.block(yes if self.expr(cond).item() else no)
            elif tag == 'for':
                name, start, stop, step, nested = args
                lo, hi, stride = (int(self.expr(x).item()) for x in (start, stop, step))
                if stride > 0:
                    for i in range(lo, hi, stride):
                        self.regs[name] = i
                        self.block(nested)
            elif tag == 'store':
                name, offset, value, mask = args
                region = self.memory[name]
                _storage_dtype(value[1], region)
                data = self.expr(value)
                active, index = _coordinates(region, self.expr(offset),
                                             np.asarray(True) if mask is None else self.expr(mask), data.shape)
                values = data[active]
                if value[1] in ('int', 'nat'):
                    bounds = np.iinfo(region.dtype)
                    if np.any(values < bounds.min) or np.any(values > bounds.max):
                        raise ValueError('integer store exceeds declared memory format')
                if index.size < 2 or np.all(index[1:] > index[:-1]):
                    region.flat[index] = values
                else:
                    # Structural lane order disambiguates repeated addresses.
                    for dst, item in zip(index, values):
                        region.flat[dst] = item
            else:
                raise ValueError(f'unsupported exported statement {tag!r}')


def run_kernel(program, memory, grid=(1,), registers=None):
    """Run all CTAs serially and return private C-contiguous copies of the regions."""
    grid = tuple(grid)
    if not 1 <= len(grid) <= 3 or any(type(n) is not int or n < 0 for n in grid):
        raise ValueError('grid requires one to three nonnegative integer dimensions')
    ports = set(program['inputs']) | set(program['outputs'])
    if not ports <= memory.keys():
        raise ValueError(f'missing memory regions: {sorted(ports - memory.keys())}')
    grid += (1,) * (3 - len(grid))
    mem = {name: np.array(value, copy=True, order='C') for name, value in memory.items()}
    with np.errstate(all='ignore'):
        for pid in product(*(range(n) for n in grid)):
            _CTA(mem, registers or {}, pid, grid).block(program['body'])
    return mem


def _bindings(values, parser):
    result = {}
    for binding in values:
        name, sep, path = binding.partition('=')
        if not sep or not name or not path or name in result:
            parser.error('expected a unique REGION=PATH binding')
        result[name] = path
    return result


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('program')
    parser.add_argument('--grid', default='1')
    parser.add_argument('--tensor', action='append', default=[], metavar='REGION=FILE')
    parser.add_argument('--output', action='append', required=True, metavar='REGION=FILE')
    args = parser.parse_args(argv)
    tensors = {name: tensorfile.read(path) for name, path in _bindings(args.tensor, parser).items()}
    outputs = _bindings(args.output, parser)
    module = runpy.run_path(args.program)
    if not outputs.keys() <= set(module['PROGRAM']['outputs']):
        parser.error('output binding must name an exported output')
    arrays = {name: np.frombuffer(t.data, dtype=DTYPES[t.dtype].newbyteorder('<')).reshape(t.shape)
              for name, t in tensors.items()}
    result = module['run'](arrays, grid=tuple(int(n) for n in args.grid.split(',')))
    for name, path in outputs.items():
        old = tensors[name]
        data = np.asarray(result[name], dtype=DTYPES[old.dtype].newbyteorder('<'))
        tensorfile.write(path, tensorfile.Tensor(old.dtype, data.shape, data.tobytes(order='C')))


if __name__ == '__main__':
    main()
